from datetime import date, timedelta
from collections import defaultdict


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays is not None else set()
        # Mapping: employee -> year -> list of dates taken
        self._used_leave: dict[str, dict[int, set[date]]] = defaultdict(lambda: defaultdict(set))

    def _is_working_day(self, d: date) -> bool:
        # Monday is 0 and Sunday is 6; 0-4 are weekdays
        return d.weekday() < 5 and d not in self.holidays

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        if end < start:
            raise ValueError("End date cannot be before start date.")

        if (start - today).days < 3:
            raise ValueError("Leave requests must be made at least 3 days in advance.")

        # Determine all working days in the requested interval, grouped by year
        requested_days_by_year: dict[int, list[date]] = defaultdict(list)
        current = start
        while current <= end:
            if self._is_working_day(current):
                requested_days_by_year[current.year].append(current)
            current += timedelta(days=1)

        # Validate that the employee has enough leave remaining for each affected year
        for year, days in requested_days_by_year.items():
            # Exclude days that might already be booked if overlapping
            new_days = [d for d in days if d not in self._used_leave[employee][year]]
            if len(new_days) > self.remaining(employee, year):
                raise ValueError(f"Insufficient leave days remaining for year {year}.")

        # Deduct / record the leave days
        total_days_used = 0
        for year, days in requested_days_by_year.items():
            for d in days:
                if d not in self._used_leave[employee][year]:
                    self._used_leave[employee][year].add(d)
                    total_days_used += 1

        return total_days_used

    def remaining(self, employee: str, year: int) -> int:
        """Returns the number of remaining leave days for an employee in a given year."""
        used = len(self._used_leave[employee][year])
        return max(0, self.days_per_year - used)
